create table MB_EVENT_ATTR (EVENT_TYPE VARCHAR(20) not null  ,SEQ_NO VARCHAR(50) not null  ,ASSEMBLE_ID VARCHAR(50) null  ,ASSEMBLE_TYPE VARCHAR(10) null  ,ASSEMBLE_RULE VARCHAR(1) null  ,ATTR_VALUE VARCHAR(50) null  ,COMPANY VARCHAR(20) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(EVENT_TYPE,SEQ_NO,COMPANY));